'use client';

import React from 'react';

interface Agent {
    id: string;
    name: string;
    role: string;
    status: string;
    position: { x: number; y: number };
}

interface Relationship {
    from: string;
    to: string;
    label: string;
}

interface Activity {
    id: number;
    agent: string;
    action: string;
    time: string;
}

interface OrchestrationPanelProps {
    agents: Agent[];
    relationships: Relationship[];
    activityFeed: Activity[];
}

export const OrchestrationPanel: React.FC<OrchestrationPanelProps> = ({ agents, relationships, activityFeed }) => {
    return (
        <div className="relative w-full h-full bg-black/5 rounded-xl border border-white/5 overflow-hidden">
            <svg className="w-full h-full" viewBox="0 0 100 100">
                {/* Relationship Lines */}
                {relationships.map((rel, idx) => {
                    const fromAgent = agents.find(a => a.id === rel.from);
                    const toAgent = agents.find(a => a.id === rel.to);
                    if (!fromAgent || !toAgent) return null;

                    return (
                        <path
                            key={idx}
                            d={`M ${fromAgent.position.x} ${fromAgent.position.y} L ${toAgent.position.x} ${toAgent.position.y}`}
                            stroke="rgba(0, 210, 255, 0.4)"
                            strokeWidth="0.8"
                            fill="none"
                            className="drop-shadow-[0_0_5px_rgba(0,210,255,0.3)]"
                            strokeDasharray="1,2"
                        />
                    );
                })}

                {/* Agent Nodes */}
                {agents.map((agent) => (
                    <g key={agent.id} transform={`translate(${agent.position.x}, ${agent.position.y})`}>
                        <circle
                            r="6"
                            className={`fill-[#0B1221] stroke-1 ${agent.status === 'active' ? 'stroke-cyan-400' :
                                agent.status === 'working' ? 'stroke-amber-400' :
                                    agent.status === 'blocked' ? 'stroke-rose-400' : 'stroke-slate-700'
                                }`}
                        />
                        <circle
                            r="2"
                            className={`${agent.status === 'active' ? 'fill-cyan-400 animate-pulse' :
                                agent.status === 'working' ? 'fill-amber-400' :
                                    agent.status === 'blocked' ? 'fill-rose-400' : 'fill-slate-600'
                                }`}
                        />
                        <text
                            y="12"
                            textAnchor="middle"
                            className="text-[3px] fill-slate-300 font-bold uppercase tracking-tighter"
                        >
                            {agent.name.split(' ')[0]}
                        </text>
                        <text
                            y="15"
                            textAnchor="middle"
                            className="text-[2px] fill-slate-600 font-medium uppercase tracking-[0.1em]"
                        >
                            {agent.id}
                        </text>
                    </g>
                ))}
            </svg>

            {/* Overlay info */}
            <div className="absolute bottom-4 left-4 p-3 bg-[#0B1221]/80 rounded-lg border border-white/10 backdrop-blur-md">
                <p className="text-[10px] text-slate-500 uppercase tracking-tighter mb-1 font-bold">Orchestration Health</p>
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2">
                        <div className="w-1.5 h-1.5 rounded-full bg-cyan-400" />
                        <span className="text-[10px] font-bold text-white">88% Efficiency</span>
                    </div>
                </div>
            </div>

            <div className="absolute top-4 right-4 text-right space-y-1">
                {['pm', 'uiux', 'dev'].map(id => (
                    <div key={id} className="text-[8px] font-bold uppercase tracking-widest text-slate-500">
                        Agent {id}: <span className="text-cyan-400">65% Utilization</span>
                    </div>
                ))}
            </div>
        </div>
    );
};
