import { GlassPanel } from './GlassPanel';

interface AgentCardProps {
    handle: string;
    name: string;
    role: string;
    status: 'active' | 'working' | 'blocked' | 'standby';
}

export function AgentCard({ handle, name, role, status }: AgentCardProps) {
    const getStatusConfig = (s: string) => {
        switch (s) {
            case 'active': return { label: 'On Track', color: 'text-cyan-400' };
            case 'working': return { label: 'Pending', color: 'text-amber-400' };
            case 'blocked': return { label: 'Blocked', color: 'text-rose-400' };
            case 'standby': return { label: 'Standby', color: 'text-slate-400' };
            default: return { label: 'On Track', color: 'text-cyan-400' };
        }
    };

    const config = getStatusConfig(status);

    return (
        <GlassPanel hoverable className="p-3 flex flex-col items-center gap-2 text-center min-w-[140px] border-white/5 bg-white/[0.02]">
            <div className="relative">
                <div className={`w-14 h-14 rounded-full overflow-hidden border-2 border-white/10 p-0.5`}>
                    <div className="w-full h-full rounded-full bg-slate-800 flex items-center justify-center text-xl font-bold text-white/50">
                        {name.charAt(0)}
                    </div>
                </div>
                <div className={`absolute -top-1 -right-1 w-3 h-3 rounded-full border-2 border-[#0B1221] ${status === 'active' ? 'bg-emerald-500' : 'bg-amber-500'}`} />
            </div>

            <div className="mt-1">
                <div className="font-bold text-sm text-white truncate w-full">{name}</div>
                <div className="text-[10px] text-slate-500 font-medium uppercase tracking-tight">{handle}</div>
            </div>

            <div className="flex flex-col gap-0.5 mt-1">
                <div className="text-[9px] text-slate-600 uppercase tracking-widest font-bold">Status</div>
                <div className={`text-[10px] font-bold uppercase tracking-wide ${config.color}`}>
                    {config.label}
                </div>
            </div>
        </GlassPanel>
    );
}
